function normalize(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\.[a-z0-9]{2,4}$/i,'').replace(/[_\-.]+/g,' ').replace(/\s+/g,' ').trim();}
const ALIASES=[{"codigo":"RAZAO","termos":["livro razao","razao contabil","razao analitico"]},{"codigo":"FAT_INTRAGRUPO","termos":["faturamento intragrupo","fat intragrupo","faturamento intra grupo"]},{"codigo":"FATURAMENTO_24M","termos":["faturamento 24m","faturamento 36","faturamento","receita bruta","receita"]},{"codigo":"CONTRATO_SOCIAL","termos":["contrato social","estatuto social","alteracao contratual","estatuto"]},{"codigo":"MUTUOS","termos":["mutuos","mutuo","relacao de mutuos","contas intragrupo"]},{"codigo":"COMBINADO","termos":["combinado","combinada","demonstracoes combinadas","df combinada"]},{"codigo":"FLUXO_CAIXA","termos":["fluxo de caixa","fluxo caixa","dfc","cash flow","fluxo"]},{"codigo":"DRE","termos":["dre","demonstracao de resultado","demonstracao do resultado","resultado do exercicio"]},{"codigo":"BALANCO","termos":["balanco patrimonial","balanco","bp"]},{"codigo":"DMPL","termos":["dmpl","mutacoes do patrimonio","mutacoes patrimonio","demonstracao das mutacoes"]},{"codigo":"DVA","termos":["dva","valor adicionado"]},{"codigo":"BALANCETE","termos":["balancete"]},{"codigo":"DF_AUDITADA","termos":["demonstracoes financeiras auditadas","df auditada","demonstracoes auditadas","demonstracoes contabeis","demonstracoes financeiras","demonstracao contabil","demonstracoes contabeis completas","dfs"]},{"codigo":"MAPA_DIVIDA","termos":["mapa de divida","mapa divida","posicao de divida"]},{"codigo":"EXTRATO_BANCARIO","termos":["extrato bancario","extrato"]},{"codigo":"AGING_AR","termos":["aging de recebiveis","aging ar","contas a receber","aging de contas a receber"]},{"codigo":"AGING_AP","termos":["aging de pagaveis","aging ap","contas a pagar","fornecedores"]},{"codigo":"ESTOQUE","termos":["estoque","estoques"]},{"codigo":"CERTIDOES","termos":["certidao","certidoes","cnd"]},{"codigo":"CONTINGENCIAS","termos":["contingencia","contingencias","processos judiciais"]},{"codigo":"SITUACAO_FISCAL","termos":["situacao fiscal","parcelamento","refis"]},{"codigo":"